style.css:
@-moz-document domain("google.com") {
/* Background Image */
    body {
        background: url('https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQCZuaVMTAStHAy-shmWkKcKN2ONrS_oszIVg&s') no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Google Logo Replacement */
    img[alt='Google'] {
        content: url('https://w7.pngwing.com/pngs/546/745/png-transparent-logo-bleach-symbol-brand-manga-bleach-template-text-manga-thumbnail.png') !important;
        width: 150px !important;
    }

    /* Search Bar Customization */
    input[type='text'] {
        border: none !important;
        border-radius: 30px !important;
        padding: 12px 20px !important;
        background: linear-gradient(135deg, #ff7300, #000000, #ffffff) !important;
        color: white !important;
        font-size: 18px !important;
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.3) !important;
        outline: none !important;
        width: 60% !important;
    }

    /* Placeholder Text Color */
    input[type='text']::placeholder {
        color: white !important;
    }
}
